INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(15801, 'Proverbs 14:17', 'Proverbs', 14, 17, '&nbsp;تاوجن خلق کم عقل کارونه کوى، او د چالاکه انسان نه خلق نفرت کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15802, 'Proverbs 14:18', 'Proverbs', 14, 18, '&nbsp;ساده ګان په ميراث کښې کم عقلتوب پرېږدى، خو هوښيارانو ته د عِلم تاج ورپه سر وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15803, 'Proverbs 14:19', 'Proverbs', 14, 19, '&nbsp;بدکاره انسانان به د نېکانو په حضور کښې، او شريران به د صادقانو په دروازو کښې په سجده شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15804, 'Proverbs 14:20', 'Proverbs', 14, 20, '&nbsp;غريب د هيچا خوښ نۀ وى، تر دې چې خپل ګاونډيان يې هم نۀ خوښوى، خو مالداره ډېر دوستان لرى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15805, 'Proverbs 14:21', 'Proverbs', 14, 21, '&nbsp;هغه څوک چې خپل ګاونډى سپک ګڼى ګناه کوى، خو بختور دے هغه څوک چې په غريب رحم کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15806, 'Proverbs 14:22', 'Proverbs', 14, 22, '&nbsp;کۀ څوک بدې ارادې لرى، هغه به ګمراه شى، کۀ څوک نېکې ارادې لرى، هغه به مينه او وفا ومومى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15807, 'Proverbs 14:23', 'Proverbs', 14, 23, '&nbsp;ټول سخت کارونه فائده ورکوى، خو د تشو خبرو په وجه غربت راځى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15808, 'Proverbs 14:24', 'Proverbs', 14, 24, '&nbsp;د هوښيارانو مال دولت د دوئ تاج دے، خو د ناپوهه هار صرف کم عقلتوب دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15809, 'Proverbs 14:25', 'Proverbs', 14, 25, '&nbsp;يو رښتونے ګواه ژوند بچ کوى، خو دروغژن ګواه دوکه مار وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15810, 'Proverbs 14:26', 'Proverbs', 14, 26, '&nbsp;هغه څوک چې د مالِک خُدائ نه يره کوى هغه به د هغۀ محفوظه قلعه وى، او د هغۀ ماشومانو ته به دا پناه ګاه وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15811, 'Proverbs 14:27', 'Proverbs', 14, 27, '&nbsp;د مالِک خُدائ يره د ژوندون سرچينه ده، کوم چې انسان د مرګ د دامونو نه ساتى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15812, 'Proverbs 14:28', 'Proverbs', 14, 28, '&nbsp;په ګڼو خلقو د بادشاه عزت جوړ وى، او د خلقو نشتوالے د شهزاده تباهى ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15813, 'Proverbs 14:29', 'Proverbs', 14, 29, '&nbsp;صبرناک سړے لويه پوهه لرى، خو غصه ناک سړے خپل کم عقلتوب په ګوته کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15814, 'Proverbs 14:30', 'Proverbs', 14, 30, '&nbsp;پُرسکونه زړۀ بدن له ژوندون ورکوى، خو حسد هډُوکى بوسه کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15815, 'Proverbs 14:31', 'Proverbs', 14, 31, '&nbsp;څوک چې په غريبانانو ظلم کوى نو دا د هغوئ د خالِق بې‌عزتى کوى، خو څوک چې په ضرورتمند رحم کوى د خُدائ پاک احترام کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15816, 'Proverbs 14:32', 'Proverbs', 14, 32, '&nbsp;بدکاران په خپلو بدو عملونو سره خپل ځان تباه کوى، خو تر دې چې صادقان په مرګ کښې هم پناه ګاه لرى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15817, 'Proverbs 14:33', 'Proverbs', 14, 33, '&nbsp;د هوښيارانو په زړۀ کښې حِکمت ځائ نيسى، خو تر دې چې حِکمت په کم عقلو کښې هم خپل ځان ښکاره کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15818, 'Proverbs 14:34', 'Proverbs', 14, 34, '&nbsp;صداقت سره قوم عظيم شى او ګناه د هر چا دپاره رسوائى ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15819, 'Proverbs 14:35', 'Proverbs', 14, 35, '&nbsp;بادشاه په هوښيار نوکر خوشحاليږى، خو هغه څوک چې شرمېدلى کارونه کوى د هغۀ قهر راوچتوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15820, 'Proverbs 15:1', 'Proverbs', 15, 1, '&nbsp;نرم جواب غصه سړوى، خو سخته خبره غصه لمبه کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15821, 'Proverbs 15:2', 'Proverbs', 15, 2, '&nbsp;د هوښيارانو ژبه عِلم خوندور کوى، خو د بې‌وقوفه خولۀ د کم عقلتوب سرچينه ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15822, 'Proverbs 15:3', 'Proverbs', 15, 3, '&nbsp;د مالِک خُدائ سترګې هر چرته موجودې دى، هغه ښۀ او بد دواړو باندې نظر ساتى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15823, 'Proverbs 15:4', 'Proverbs', 15, 4, '&nbsp;نرمه ژبه د ژوندون ونه ده، خو ټګماره ژبه روح ماتوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15824, 'Proverbs 15:5', 'Proverbs', 15, 5, '&nbsp;کم عقل د خپل پلار تربيت ته سپک ګورى، خو هر هغه څوک چې اصلاح قبلوى نو هغه هوښيار دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15825, 'Proverbs 15:6', 'Proverbs', 15, 6, '&nbsp;د صادق په کور کښې لويه خزانه وى، خو د بدکاره ګټه هغوئ ته تکليف ورکوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15826, 'Proverbs 15:7', 'Proverbs', 15, 7, '&nbsp;د هوښيارانو شونډې عِلم خوروى، خو د بې‌عقله په زړۀ کښې داسې څۀ نۀ وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15827, 'Proverbs 15:8', 'Proverbs', 15, 8, '&nbsp;مالِک خُدائ د بدکارانو د قربانۍ نه نفرت کوى، خو د نېکانو دُعا هغه خوشحالوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15828, 'Proverbs 15:9', 'Proverbs', 15, 9, '&nbsp;مالِک خُدائ د بدکارانو د چال چلن نه نفرت کوى، خو هغه د هغوئ سره مينه کوى څوک چې صداقت پسې روان وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15829, 'Proverbs 15:10', 'Proverbs', 15, 10, '&nbsp;د هغه چا به سخت تربيت وشى څوک چې صحيح لاره پرېږدى، څوک چې د اِصلاح کولو نه نفرت کوى نو هغه به مړ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15830, 'Proverbs 15:11', 'Proverbs', 15, 11, '&nbsp;دا چې عالمِ ارواح او دوزخ دواړه مالِک خُدائ ته ښکارى، نو د انسان زړۀ به ورته څومره زيات څرګند وى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15831, 'Proverbs 15:12', 'Proverbs', 15, 12, '&nbsp;مسخره کوونکى اصلاح نۀ خوښوى، نو ځکه چې د هوښيارانو سره مشوره نۀ کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15832, 'Proverbs 15:13', 'Proverbs', 15, 13, '&nbsp;خوشحاله زړۀ مخ شادابه ښائى، خو پرېشانه زړۀ د انسان روح ماتوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15833, 'Proverbs 15:14', 'Proverbs', 15, 14, '&nbsp;د هوښيارانو زړۀ د عِلم لټون کوى، خو د کم عقل خولۀ په ناپوهۍ کښې څريږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15834, 'Proverbs 15:15', 'Proverbs', 15, 15, '&nbsp;د مظلومانو د ژوند ټولې ورځې خرابې وى، خو خوشحاله زړۀ هر وخت جشن کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15835, 'Proverbs 15:16', 'Proverbs', 15, 16, '&nbsp;د مالِک خُدائ په يره کښې لږ آمدن غوره دے، د هغه ډېر مال دولت نه چې سکون په کښې نۀ وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15836, 'Proverbs 15:17', 'Proverbs', 15, 17, '&nbsp;دال ساګ دې وى خو چې مينې سره وى، کۀ چرګ وى او نفرت ورسره وى نو فائده يې څۀ ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15837, 'Proverbs 15:18', 'Proverbs', 15, 18, '&nbsp;غصه ناک سړے صرف لانجه جوړوى، خو صبرناک سړے جنګونه سړوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15838, 'Proverbs 15:19', 'Proverbs', 15, 19, '&nbsp;د ناراسته لار د ازغو ډکه وى، خو د نېکانو لارې لکه د پوخ سړک په شان وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15839, 'Proverbs 15:20', 'Proverbs', 15, 20, '&nbsp;هوښيار زوئ د خپل پلار دپاره د خوشحالۍ ذريعه ده، خو بې‌وقوفه خپلې مور ته سپک ګورى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15840, 'Proverbs 15:21', 'Proverbs', 15, 21, '&nbsp;کم عقلتوب هغه سړے خوشحالوى څوک چې ناپوهه وى، خو هوښيار سړے په سيدها لار روان وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15841, 'Proverbs 15:22', 'Proverbs', 15, 22, '&nbsp;چرته چې صلاح مشوره نۀ وى نو هلته منصوبې ناکامه شى، خو د ډېرو مشوره ورکوونکو په ذريعه کاميابې حاصليږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15842, 'Proverbs 15:23', 'Proverbs', 15, 23, '&nbsp;انسان په مناسب جواب ورکولو خوشحاليږى، په مناسب وخت کښې ټيک خبره کول څومره ښۀ وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15843, 'Proverbs 15:24', 'Proverbs', 15, 24, '&nbsp;د هوښيارانو لار هغه بره د ژوندون طرف ته بوځى، چې هغه قبر ته لاندې د تلو نه وساتى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15844, 'Proverbs 15:25', 'Proverbs', 15, 25, '&nbsp;مالِک خُدائ د مغرور کور سر د لاندې راغورزوى، خو هغه د کونډې جائيداد محفوظ ساتى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15845, 'Proverbs 15:26', 'Proverbs', 15, 26, '&nbsp;مالِک خُدائ د بدو منصوبو نه نفرت کوى، خو هغه په پاکو خبرو خوشحاليږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15846, 'Proverbs 15:27', 'Proverbs', 15, 27, '&nbsp;لالچى خپل خاندان ته مصيبت ورپه برخه کوى، خو هغه څوک چې د رشوت نه نفرت کوى هغوئ به ژوندى پاتې شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15847, 'Proverbs 15:28', 'Proverbs', 15, 28, '&nbsp;صادقان د جواب ورکولو نه وړاندې سوچ کوى، خو د بدکاره خولۀ فساد نولى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15848, 'Proverbs 15:29', 'Proverbs', 15, 29, '&nbsp;مالِک خُدائ د بدعمله خلقو نه لرې وى، خو هغه د صادقانو دُعاګانې اورى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15849, 'Proverbs 15:30', 'Proverbs', 15, 30, '&nbsp;روڼ تندے زړۀ ته خوشحالى ورکوى، او ښۀ زيرے بدن تازه کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15850, 'Proverbs 15:31', 'Proverbs', 15, 31, '&nbsp;هغه څوک چې ښې رټنې ته غوږ نيسى، نو هغوئ به په هوښيارانو کښې وشميرلے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15851, 'Proverbs 15:32', 'Proverbs', 15, 32, '&nbsp;هغه څوک چې تربيت رد کوى د خپل ځان سپکاوے کوى، خو هغه څوک چې تربيت قبلوى نو دے عقلمندى حاصلوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15852, 'Proverbs 15:33', 'Proverbs', 15, 33, '&nbsp;د مالِک خُدائ يره حِکمت پېدا کوى، عاجزى د عزت وړومبے قدم دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15853, 'Proverbs 16:1', 'Proverbs', 16, 1, '&nbsp;انسان په خپل زړۀ کښې منصوبې جوړوى، خو د هغوئ فېصلې مالِک خُدائ کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15854, 'Proverbs 16:2', 'Proverbs', 16, 2, '&nbsp;د انسان په نظر کښې د هغۀ ټولې لارې هغۀ ته پاکې ښکارى، خو مالِک خُدائ د هغۀ نيت آزمائى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15855, 'Proverbs 16:3', 'Proverbs', 16, 3, '&nbsp;هر يو کار چې تۀ کوې هغه مالِک خُدائ ته سپاره، نو ستا منصوبې به کاميابې شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15856, 'Proverbs 16:4', 'Proverbs', 16, 4, '&nbsp;مالِک خُدائ هر څۀ د خپل مقصد د پوره کولو دپاره پېدا کړى دى، تر دې چې بدکاران يې هم د تباهۍ د ورځې دپاره پېدا کړى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15857, 'Proverbs 16:5', 'Proverbs', 16, 5, '&nbsp;مالِک خُدائ د ټولو مغروره خلقو نه نفرت کوى. په دې يقين لرئ چې دوئ به بې‌سزا پاتې نۀ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15858, 'Proverbs 16:6', 'Proverbs', 16, 6, '&nbsp;د مينې او وفا په ذريعه ګناهونه وينځلے کيږى، د مالِک خُدائ يره انسان د بدو کارونو نه بچ کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15859, 'Proverbs 16:7', 'Proverbs', 16, 7, '&nbsp;کله چې مالِک خُدائ د چا د کردار نه خوشحاله وى، نو د هغۀ دشمنان به هم د هغۀ په امن کښې اوسيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15860, 'Proverbs 16:8', 'Proverbs', 16, 8, '&nbsp;په صداقت سره لږه ګټه ښۀ ده د هغه ډيرې ګټې نه چې په بې‌اِنصافۍ وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15861, 'Proverbs 16:9', 'Proverbs', 16, 9, '&nbsp;انسان په خپل زړۀ کښې ځان ته د تګ لاره جوړوى، خو مالِک خُدائ د هغۀ د قدمونو رهنمائى کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15862, 'Proverbs 16:10', 'Proverbs', 16, 10, '&nbsp;د بادشاه خبرې درنې وى، نو په کار دے چې هغه اِنصاف پټ نۀ کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15863, 'Proverbs 16:11', 'Proverbs', 16, 11, '&nbsp;صحيح تله او ناپ کول د مالِک خُدائ د طرفه دى، هغۀ د اِنصاف معيار قائم کړے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15864, 'Proverbs 16:12', 'Proverbs', 16, 12, '&nbsp;بادشاهان د غلط کارونو نه نفرت کوى، ځکه چې د هغوئ تخت د صداقت په بنياد جوړ دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15865, 'Proverbs 16:13', 'Proverbs', 16, 13, '&nbsp;بادشاهان د رښتينو شونډو نه خوشحاليږى، او هغوئ هغه انسان سره مينه کوى څوک چې رښتيا وائى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15866, 'Proverbs 16:14', 'Proverbs', 16, 14, '&nbsp;د بادشاه غضب د مرګ پېغام دے، خو هوښيار انسان به د هغۀ قهر سړوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15867, 'Proverbs 16:15', 'Proverbs', 16, 15, '&nbsp;هر کله چې د بادشاه تندے روڼ وى نو دا د ژوندون زېرے دے، نو په دې وخت کښې د هغۀ رحم داسې وى لکه د سپرلى وريځې چې باران ورَوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15868, 'Proverbs 16:16', 'Proverbs', 16, 16, '&nbsp;د حِکمت حاصلول د سرو زرو نه څو چنده ښۀ دے، او د عقل حاصلول د سپينو زرو نه څو چنده ښۀ دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15869, 'Proverbs 16:17', 'Proverbs', 16, 17, '&nbsp;د نېکانو لارې د هر قسم غلط کار نه لرې وى. هر هغه څوک چې د خپلو لارو خيال ساتى نو هغه خپل ژوند بچ کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15870, 'Proverbs 16:18', 'Proverbs', 16, 18, '&nbsp;غرور انسان د تباهۍ طرف ته بوځى، او د راپرېوتلو نه وړاندې تکبر راځى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15871, 'Proverbs 16:19', 'Proverbs', 16, 19, '&nbsp;د انسان دپاره دا بهتره ده چې عاجز خويه وى او د مظلومانو سره ناسته پاسته کوى، د دې په ځائ چې د مغرورانو په غنيمتونو کښې شريک شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15872, 'Proverbs 16:20', 'Proverbs', 16, 20, '&nbsp;هر څوک چې لارښودنو ته توجو ورکړى نو کامياب به وى، او بختور دے هغه څوک چې په مالِک خُدائ باور کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15873, 'Proverbs 16:21', 'Proverbs', 16, 21, '&nbsp;څوک چې هوښيار وى هغه تميزدار ګڼلے شى، نرمې خبرې په هدايت کولو کښې ښۀ اثر کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15874, 'Proverbs 16:22', 'Proverbs', 16, 22, '&nbsp;د هغه چا دپاره حِکمت د ژوند سرچينه ده څوک يې چې لرى. خو کم عقلتوب د بې‌وقوفه دپاره د سزا باعث کيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15875, 'Proverbs 16:23', 'Proverbs', 16, 23, '&nbsp;د قابل سړى‎‎‎‎‎‎‎‎‎ ‎زړۀ ‎‎د هغۀ خولۀ قابو کوى، او د هغۀ کلام موثر کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15876, 'Proverbs 16:24', 'Proverbs', 16, 24, '&nbsp;نرمې خبرې د شاتو د ګبين په شان وى، د ځان دپاره خوږې او د هډوکو دپاره درمان وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15877, 'Proverbs 16:25', 'Proverbs', 16, 25, '&nbsp;يوه داسې لار شته چې انسان ته صحيح ښکارى، خو په آخر کښې هغه د مرګ طرف ته تلې وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15878, 'Proverbs 16:26', 'Proverbs', 16, 26, '&nbsp;د مزدور لوږه هغه په کار لګيا کوى، ځکه چې هغه خپله لوږه ختمول غواړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15879, 'Proverbs 16:27', 'Proverbs', 16, 27, '&nbsp;بدعمله داسې کار لټوى چې نورو ته ترې نه تکليف ورسيږى، د هغوئ خبرې هم سوزونکے اور ورَوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15880, 'Proverbs 16:28', 'Proverbs', 16, 28, '&nbsp;بدکاره انسان لانجه جوړوى، چغلخور نزدې دوستان په خپلو کښې جدا کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15881, 'Proverbs 16:29', 'Proverbs', 16, 29, '&nbsp;ظالمان خپل دوستان بې‌لارې کوى او د تباهۍ طرف ته يې بوځى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15882, 'Proverbs 16:30', 'Proverbs', 16, 30, '&nbsp;هر هغه څوک چې سترګې وروځې وهى هغه کږې وَږې منصوبې جوړوى، او څوک چې خپلې شونډې مروړى نو هغه په غلطو منصوبو سر شوى وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15883, 'Proverbs 16:31', 'Proverbs', 16, 31, '&nbsp;سپين وېښتۀ د عزت تاج دے، کوم چې د صداقت د ژوندون نه حاصليږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15884, 'Proverbs 16:32', 'Proverbs', 16, 32, '&nbsp;صبرناک انسان د يو طاقتور سپاهى نه بهتر دے، څوک چې په خپله غصه قابو ساتى، د هغه چا نه بهتر دے چې يو ښار فتح کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15885, 'Proverbs 16:33', 'Proverbs', 16, 33, '&nbsp;انسان خو مېدان ته چکه ولى، خو د هر چا فېصله د مالِک خُدائ په لاس کښې وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15886, 'Proverbs 17:1', 'Proverbs', 17, 1, '&nbsp;د سکون سره سپوره روټۍ بهتره ده د هغې کور نه چې په کښې ښۀ خوراکونه د لانجو سره وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15887, 'Proverbs 17:2', 'Proverbs', 17, 2, '&nbsp;يو هوښيار نوکر به د مالِک په شرمېدلى زوئ باندې حُکم چلوى، او په ميراث کښې به ورته حِصه هم لکه د يو ورور په شان مِلاو شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15888, 'Proverbs 17:3', 'Proverbs', 17, 3, '&nbsp;سرۀ زر او سپين زر په اور معلومولے شى، خو زړونه مالِک خُدائ معلوموى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15889, 'Proverbs 17:4', 'Proverbs', 17, 4, '&nbsp;بدکاره انسان خرابو خبرو ته غوږ نيسى او دروغژن غېبت ته توجو ورکوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15890, 'Proverbs 17:5', 'Proverbs', 17, 5, '&nbsp;هر هغه څوک چې په غريبانانو پورې خندا کوى، نو د هغۀ د خالِق بې‌عزتى کوى او هر هغه څوک چې د چا په بدبختۍ خوشحاليږى نو دے به هم بې‌سزا پاتې نۀ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15891, 'Proverbs 17:6', 'Proverbs', 17, 6, '&nbsp;نمسى د خپلو مشرانو دپاره تاج وى، او ماشومان په مور پلار فخر کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15892, 'Proverbs 17:7', 'Proverbs', 17, 7, '&nbsp;کۀ هوښيارې خبرې د يو کم عقل دپاره نامناسبه وى، نو د يو بادشاه دپاره به دروغژنې شونډې څومره نامناسبه وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15893, 'Proverbs 17:8', 'Proverbs', 17, 8, '&nbsp;رشوت د ورکوونکى دپاره د جادو په شان وى، ځکه هغه چې هر څۀ کوى نو کاميابيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15894, 'Proverbs 17:9', 'Proverbs', 17, 9, '&nbsp;هر هغه څوک چې د نورو خطاګانې معاف کوى نو مينې ته وده ورکوى، خو هر هغه څوک چې يوه خبره بار بار تکراروى نو نزدې دوستان سره جدا کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15895, 'Proverbs 17:10', 'Proverbs', 17, 10, '&nbsp;يو هوښيار کس په يو ځل تنبيه کولو سره دومره زيات متاثره کيږى، نه چې يو کم عقل په سلو کوړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15896, 'Proverbs 17:11', 'Proverbs', 17, 11, '&nbsp;بدکاره صرف سرکشۍ پسې ليونى وى، خو دوئ ته به سخته سزا مِلاو شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15897, 'Proverbs 17:12', 'Proverbs', 17, 12, '&nbsp;دا بهتره ده چې د هغې مېلوګى سره دې واسطه راشى چې بچى ترې چا پټ کړى وى په ځائ د دې چې يو بې‌وقوفه په خپل کم عقلتوب ټينګار کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15898, 'Proverbs 17:13', 'Proverbs', 17, 13, '&nbsp;کۀ چرته يو انسان د ښو په بدل کښې بد کوى، نو د هغۀ د کور نه به هيڅکله بدى ختمه نۀ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15899, 'Proverbs 17:14', 'Proverbs', 17, 14, '&nbsp;د خراب بحث شروع داسې وى لکه چې د اوبو په بند کښې وړومبے سورے وشى، د دې نه مخکښې چې جنګ شروع نۀ شى نو دا زر ختم کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15900, 'Proverbs 17:15', 'Proverbs', 17, 15, '&nbsp;بدعمله کس پرېښودل، او بې‌ګناه له سزا ورکول، مالِک خُدائ د دې دواړو کارونو نه نفرت کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');